(()=>{const $=s=>document.querySelector(s),audio=$('audio');let items=[],current=-1,kind='全部',lastSave=0;const prefix='aione1.library.'+location.pathname;function load(k,fallback){try{return JSON.parse(localStorage.getItem(prefix+k))??fallback}catch{return fallback}}function store(k,v){try{localStorage.setItem(prefix+k,JSON.stringify(v))}catch{}}let saved=load('progress',{}),favorites=load('favorites',[]);const format=n=>{n=Math.max(0,Number(n)||0);const h=Math.floor(n/3600),m=Math.floor(n%3600/60);return h?h+' 小时 '+m+' 分':m+' 分钟'};function card(t,i){const a=document.createElement('article');a.className='album'+(i===current?' active':'');const button=document.createElement('button');button.className='album-open';button.setAttribute('aria-label','播放 '+t.title);const art=document.createElement('div');art.className='album-art';if(t.cover){const im=document.createElement('img');im.src=t.cover;im.alt='';im.loading='lazy';im.onerror=()=>im.remove();art.append(im)}const badge=document.createElement('span');badge.className='album-badge';badge.textContent=t.kind;const arrow=document.createElement('span');arrow.className='album-play';arrow.textContent='▶';art.append(badge,arrow);const body=document.createElement('div');body.className='album-body';const h=document.createElement('h2');h.textContent=t.title;const author=document.createElement('p');author.textContent=t.artist;const meta=document.createElement('small');meta.textContent=format(t.duration)+(saved[t.id]>10?' · 已听 '+format(saved[t.id]):'');body.append(h,author,meta);button.append(art,body);button.onclick=()=>select(i,true);const star=document.createElement('button');star.className='favorite';star.setAttribute('aria-label','收藏 '+t.title);star.setAttribute('aria-pressed',String(favorites.includes(t.id)));star.textContent=favorites.includes(t.id)?'★':'☆';star.onclick=()=>{favorites=favorites.includes(t.id)?favorites.filter(v=>v!==t.id):[...favorites,t.id];store('favorites',favorites);render()};a.append(button,star);return a}function render(){const q=$('#search').value.trim().toLowerCase(),root=$('#catalog');root.replaceChildren();items.forEach((t,i)=>{if(kind==='收藏'&&!favorites.includes(t.id)||!['全部','收藏'].includes(kind)&&t.kind!==kind)return;if(![t.title,t.artist,...t.tags].join(' ').toLowerCase().includes(q))return;root.append(card(t,i))});$('#empty').hidden=root.children.length>0;[...$('#kinds').children].forEach(b=>b.classList.toggle('primary',b.textContent===kind))}function select(i,play){if(!items[i])return;if(current>=0&&audio.currentTime>0){saved[items[current].id]=audio.currentTime;store('progress',saved)}current=i;const t=items[i];audio.src=t.url;$('#track').textContent=t.title;$('#artist').textContent=t.artist+' · '+t.kind;$('#cover').hidden=!t.cover;if(t.cover)$('#cover').src=t.cover;store('last',t.id);audio.onloadedmetadata=()=>{const pos=saved[t.id]||0;if(pos>5&&pos<(audio.duration||Infinity)-10)audio.currentTime=pos;audio.playbackRate=Number($('#rate').value)};if(play)audio.play().catch(()=>$('#status').textContent='请点击播放器中的播放按钮开始聆听');render();if('mediaSession'in navigator&&'MediaMetadata'in window){navigator.mediaSession.metadata=new MediaMetadata({title:t.title,artist:t.artist,album:t.kind,...(t.cover?{artwork:[{src:new URL(t.cover,location.href).href}]}:{})})}}$('#play').onclick=()=>{if(current<0&&items.length){select(0,true);return}if(audio.paused)audio.play().catch(()=>{});else audio.pause()};$('#prev').onclick=()=>items.length&&select((current-1+items.length)%items.length,true);$('#next').onclick=()=>items.length&&select((current+1)%items.length,true);audio.onplay=()=>{$('#play').textContent='暂停';$('#status').textContent='正在播放 · '+items[current].kind};audio.onpause=()=>$('#play').textContent='播放';audio.ontimeupdate=()=>{if(current>=0&&Date.now()-lastSave>5000){saved[items[current].id]=audio.currentTime;store('progress',saved);lastSave=Date.now()}};audio.onended=()=>{if(current>=0){saved[items[current].id]=0;store('progress',saved)}if(items.length)select((current+1)%items.length,true)};audio.onerror=()=>$('#status').textContent='该音频暂时无法载入，请稍后重试或选择其他内容。';$('#rate').onchange=e=>audio.playbackRate=Number(e.target.value);$('#search').oninput=render;fetch('library.json',{cache:'no-cache'}).then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{items=d.items;$('#total').textContent=items.length;for(const k of ['全部',...new Set(items.map(t=>t.kind)),'收藏']){const b=document.createElement('button');b.textContent=k;b.onclick=()=>{kind=k;render()};$('#kinds').append(b)}$('#status').textContent='曲库已就绪，选择一份声音即可播放。';render();const last=load('last','');const index=items.findIndex(t=>t.id===last);if(index>=0)select(index,false)}).catch(()=>$('#status').textContent='曲库正在同步，请稍后刷新。');window.addEventListener('beforeunload',()=>{if(current>=0){saved[items[current].id]=audio.currentTime;store('progress',saved)}})})();